/* ================= QUESTION GENERATORS =================
   Each generator returns a fresh, randomized question with recomputed answers,
   so math tests never repeat. All arithmetic is integer-safe. */
(function(){
const R = (a,b) => a + Math.floor(Math.random()*(b-a+1));
const pick = arr => arr[Math.floor(Math.random()*arr.length)];
const shuffleOpts = (correct, wrong, pads=[]) => {
  // Build 3 distinct wrong options (dedupe against correct and each other), then place
  // the correct answer at a random index.
  const seen = new Set([String(correct)]);
  const ws = [];
  for (const w of [...wrong, ...pads]) {
    const s = String(w);
    if (!seen.has(s)) { seen.add(s); ws.push(w); }
    if (ws.length === 3) break;
  }
  let pad = 7;
  while (ws.length < 3) {
    const s = typeof correct === "number" ? correct + pad : "?" + pad;
    if (!seen.has(s)) { seen.add(s); ws.push(typeof correct === "number" ? correct + pad : s); }
    pad += 4;
  }
  const a = Math.floor(Math.random()*4);
  const out = []; let w = 0;
  for (let i = 0; i < 4; i++) { out.push(i === a ? correct : ws[w++]); }
  return {ch: out, a};
};
const fmt$ = n => "$" + n.toLocaleString("en-US");

/* --- ALG: solve ax + b = c --- */
function genLinear(){
  const a=R(2,9), x=R(2,15), b=R(-12,12), c=a*x+b;
  const {ch,a:ai}=shuffleOpts(x, [x+a, x-a, x+2], [x+5, x-2, x+1]);
  return {id:"G-ALG-"+Date.now()+R(1,999), d:"ALG", tier: pick(["advanced","elite"]),
    p:`If ${a}x ${b<0?"−":"+"} ${Math.abs(b)} = ${c}, what is the value of x?`,
    q:"Solve for x.", ch, a:ai,
    e:`Isolate the variable term: ${a}x = ${c} ${b<0?"+":"−"} ${Math.abs(b)} = ${c-b}. Then x = ${c-b}/${a} = ${x}. Always substitute back: ${a}(${x}) ${b<0?"−":"+"} ${Math.abs(b)} = ${c} ✓.`};
}
/* --- ALG: 2x2 system with integer solution --- */
function genSystem(){
  const x=R(2,9), y=R(2,9);
  let a=R(1,4), b=R(1,4), d=R(1,4), e=R(1,4);
  if(a*e-b*d===0){ e+=1; }
  const c=a*x+b*y, f=d*x+e*y;
  const wrong=[x+y, x+1, y];
  const {ch,a:ai}=shuffleOpts(x, wrong, [x+2, y+1, x-1]);
  return {id:"G-ALG-"+Date.now()+R(1,999), d:"ALG", tier:"advanced",
    p:`The system below has solution (x, y):<br>${a}x + ${b}y = ${c}<br>${d}x + ${e}y = ${f}`,
    q:"What is the value of x?", ch, a:ai,
    e:`Eliminate one variable (multiply the equations if needed) and solve: the system's solution is x = ${x}, y = ${y}. Verify by substituting both values into the original equations.`};
}
/* --- ALG: slope/intercept from two points --- */
function genSlope(){
  const m=pick([1,2,3,-1,-2]), b=R(-4,8), x1=R(1,5), x2=x1+R(1,4);
  const y1=m*x1+b, y2=m*x2+b;
  const {ch,a:ai}=shuffleOpts(`y = ${m}x ${b<0?"−":"+"} ${Math.abs(b)}`,
    [`y = ${m}x ${b+2<0?"−":"+"} ${Math.abs(b+2)}`, `y = ${m+1}x ${b<0?"−":"+"} ${Math.abs(b)}`, `y = ${m}x ${b-1<0?"−":"+"} ${Math.abs(b-1)}`]);
  return {id:"G-ALG-"+Date.now()+R(1,999), d:"ALG", tier:"advanced",
    p:`Line ℓ passes through the points (${x1}, ${y1}) and (${x2}, ${y2}).`,
    q:"Which equation is the equation of line ℓ?", ch, a:ai,
    e:`Slope = (${y2} − ${y1})/(${x2} − ${x1}) = ${m}. Substitute one point into y = ${m}x + b to find b = ${b}. A wrong sign on b or an off-by-one slope is the usual trap here.`};
}
/* --- ALG: minimum-quantity inequality --- */
function genIneq(){
  const F=pick([90,96,120,150]), r=pick([0.4,0.5,0.55,0.75]);
  const n=(r===0.55||r===0.75)? R(8,20)*20 : R(16,40)*10; // keeps target a whole-dollar figure
  const T=F+r*n;
  const {ch,a:ai}=shuffleOpts(n, [n-10, n+10, Math.round(n/2)], [n+5, n-5, n+20]);
  return {id:"G-ALG-"+Date.now()+R(1,999), d:"ALG", tier:"elite",
    p:`A courier earns ${fmt$(F)} for each full day of work plus ${fmt$(r)} for each package delivered. On a given day, the courier wants to earn at least ${fmt$(T)}.`,
    q:"What is the minimum number of packages the courier must deliver that day?", ch, a:ai,
    e:`Solve ${fmt$(r)}p + ${fmt$(F)} ≥ ${fmt$(T)}: ${fmt$(r)}p ≥ ${fmt$(T-F)}, so p ≥ ${n}. Since ${T-F} divided by ${r} is exactly ${n}, the minimum is ${n} packages — "at least" means the boundary value is included.`};
}
/* --- ADV: quadratic maximum --- */
function genQuad(){
  const a=pick([2,5]), k=R(2,4), b=2*a*k, c=R(0,8);
  const max=a*k*k+c;
  const {ch,a:ai}=shuffleOpts(max, [max+a, b, max-1], [max+2, max-3, b-1]);
  return {id:"G-ADV-"+Date.now()+R(1,999), d:"ADV", tier:"elite",
    p:`A projectile's height in meters is modeled by h(t) = −${a}t<sup>2</sup> + ${b}t + ${c}, where t is the time in seconds after launch.`,
    q:"What is the maximum height the projectile reaches, in meters?", ch, a:ai,
    e:`The maximum of a downward-opening parabola sits at t = −b/(2a) = ${b}/${2*a} = ${k} seconds. Evaluate: h(${k}) = −${a}(${k*k}) + ${b}(${k}) + ${c} = ${max} meters. Remember: the question asks for the height, not the time.`};
}
/* --- ADV: exponential model identification --- */
function genExp(){
  const A=pick([120,240,500,800]), base=pick([2,3]), p=R(2,6);
  const {ch,a:ai}=shuffleOpts(`N(t) = ${A} · ${base}<sup>t/${p}</sup>`,
    [`N(t) = ${A} · ${base}<sup>${p}t</sup>`, `N(t) = ${A} · ${p}<sup>t/${base}</sup>`, `N(t) = ${A} · ${base}t/${p}`]);
  return {id:"G-ADV-"+Date.now()+R(1,999), d:"ADV", tier:"advanced",
    p:`A population starts at ${A} and multiplies by ${base} every ${p} hours.`,
    q:"Which function gives N, the population size, t hours after the start?", ch, a:ai,
    e:`A factor of ${base} per ${p} hours means the exponent must count elapsed periods: t/${p}. So N(t) = ${A} · ${base}<sup>t/${p}</sup>. The exponent ${p}t would multiply by ${base} every hour; swapping the base and period is the classic trap.`};
}
/* --- PSD: percent change composition --- */
function genPercent(){
  const combos=[[25,20],[50,40],[60,50],[40,50],[20,25],[100,50],[80,75],[25,36]];
  const [p,d]=pick(combos);
  const mult=(1+p/100)*(1-d/100);
  const pct=Math.round((mult-1)*100);
  const correct = pct===0? "Equal to the original price" : (pct>0? `${pct}% higher` : `${Math.abs(pct)}% lower`);
  const {ch,a:ai}=shuffleOpts(correct, ["5% higher","10% lower","Equal to the original price","20% higher","25% lower","15% lower"].filter(o=>o!==correct).slice(0,3));
  return {id:"G-PSD-"+Date.now()+R(1,999), d:"PSD", tier:"elite",
    p:`A price increased by ${p}%, and the new price was later discounted by ${d}%.`,
    q:"Compared with the original price, what was the final price after the discount?", ch, a:ai,
    e:`Percent changes multiply: (1 + ${p}/100) × (1 − ${d}/100) = ${mult.toFixed(2)}. That is ${pct===0?"exactly 1.00 — no net change":(pct>0? `${pct}% above 1.00`:`${Math.abs(pct)}% below 1.00`)}. Adding ${p} − ${d} = ${p-d}% directly is the trap; percentages compose multiplicatively.`};
}
/* --- PSD: missing fifth number --- */
function genMean(){
  const M=R(12,30), vals=[]; let s=0;
  for(let i=0;i<4;i++){const v=M+R(-6,6); vals.push(v); s+=v;}
  const fifth=5*M-s;
  const {ch,a:ai}=shuffleOpts(fifth, [M, fifth+2, fifth-3], [fifth+5, fifth-1, M+2]);
  return {id:"G-PSD-"+Date.now()+R(1,999), d:"PSD", tier:"advanced",
    p:`The mean of five numbers is ${M}. Four of the numbers are ${vals.join(", ")}.`,
    q:"What is the fifth number?", ch, a:ai,
    e:`Total = 5 × ${M} = ${5*M}. The four known values sum to ${s}. The fifth number is ${5*M} − ${s} = ${fifth}. Choice containing ${M} just echoes the mean — always recompute the sum yourself.`};
}
/* --- PSD: conditional probability from a two-way table --- */
function genProb(){
  const sc=pick([[8,32],[12,36],[15,45],[10,40],[12,48],[8,24]]); // [teachers-in-col, students-in-col]
  const st=R(2,9)*10, tt=R(2,8)*4;
  const total= sc[0]+sc[1]+st+tt;
  const num=sc[0], den=sc[0]+sc[1];
  const g=(a,b)=>b?g(b,a%b):a; const G=g(num,den);
  const frac=`${num/G}/${den/G}`;
  const {ch,a:ai}=shuffleOpts(frac, [`${num}/${total}`, `${sc[1]}/${den}`, `${num}/${sc[0]+st}`], ["1/2","1/4","2/5","1/10","3/8","2/3"]);
  return {id:"G-PSD-"+Date.now()+R(1,999), d:"PSD", tier:"elite",
    p:`A workshop surveyed ${total} people about their preferred session format:<br><table style='width:85%;border-collapse:collapse;font-size:.9rem'><tr style='color:var(--muted)'><th style='text-align:left;padding:4px'></th><th>Session A</th><th>Session B</th></tr><tr><td style='padding:4px'>Students</td><td style='text-align:center'>${sc[1]}</td><td style='text-align:center'>${st}</td></tr><tr><td style='padding:4px;background:var(--card2)'>Teachers</td><td style='text-align:center;background:var(--card2)'>${sc[0]}</td><td style='text-align:center;background:var(--card2)'>${tt}</td></tr></table>`,
    q:"One person is chosen at random from all who preferred Session A. What is the probability that the person is a teacher?", ch, a:ai,
    e:`“Chosen from all who preferred Session A” limits the denominator to ${den} people (Session A column). Teachers there: ${num}. Probability = ${num}/${den} = ${frac}. Using the grand total ${total} is the classic conditional-probability trap.`};
}
/* --- PSD: ratio application --- */
function genRatio(){
  const a=pick([3,4,5]), b=R(1,4), k=R(3,9);
  const given=a*k, want=b*k;
  const {ch,a:ai}=shuffleOpts(want, [given, a*b, want+a], [want+b, 2*want, a+b+1]);
  return {id:"G-PSD-"+Date.now()+R(1,999), d:"PSD", tier:"advanced",
    p:`A recipe mixes concentrate and water in a ratio of ${a} : ${b} by volume. A cook uses ${given} milliliters of concentrate.`,
    q:"How many milliliters of water are needed?", ch, a:ai,
    e:`Each “part” is ${given}/${a} = ${k} mL, so water = ${b} parts × ${k} = ${want} mL. Reversing the ratio (multiplying by ${a}/${b}) is the most common error in ratio items.`};
}
/* --- GEO: sector area --- */
function genSector(){
  const combos=[[6,60,"6π"],[12,60,"24π"],[6,90,"9π"],[3,120,"3π"],[6,120,"12π"],[6,30,"3π"]];
  const [r,ang,area]=pick(combos);
  const {ch,a:ai}=shuffleOpts(area, [`${ang/30}π`, `${r*r/4}π`, `${r}π`], ["2π","5π","8π","10π","36π"]);
  return {id:"G-GEO-"+Date.now()+R(1,999), d:"GEO", tier:"elite",
    p:`A circle has radius ${r}. A sector of the circle has a central angle of ${ang}°.`,
    q:"What is the area of the sector, in square units?", ch, a:ai,
    e:`Sector area = (${ang}/360) × πr<sup>2</sup> = (${ang}/360) × ${r*r}π = ${area}. Always reduce the angle fraction first, then multiply by the full-circle area.`};
}
/* --- GEO: sin/cos complement with 3-4-5 family --- */
function genTrig(){
  const trips=[[3,4,5,"3/5","4/5"],[6,8,10,"3/5","4/5"],[5,12,13,"5/13","12/13"],[7,24,25,"7/25","24/25"]];
  const [x,y,h,s,c]=pick(trips);
  const flip=Math.random()<0.5;
  const given=flip?c:s, want=flip?s:c;
  const {ch,a:ai}=shuffleOpts(want, [given, "1", `${y}/${x}`]);
  return {id:"G-GEO-"+Date.now()+R(1,999), d:"GEO", tier:"elite",
    p:`For an acute angle θ, sin θ = ${given}.`,
    q:"What is cos θ?", ch, a:ai,
    e:`Use sin<sup>2</sup>θ + cos<sup>2</sup>θ = 1, or picture the ${x}-${y}-${h} right triangle: the sine uses one leg, the cosine the other. So cos θ = ${want}. Cosines of acute angles are always between 0 and 1 — an option like 1 or a value above 1 can be eliminated instantly.`};
}
/* --- GEO: angle chase --- */
function genAngles(){
  const x=R(10,28), total=180;
  const k1=pick([2,3,4]), k2=pick([2,3,4]);
  // triangle: k1*x + k2*x + const = 180 → x integer
  const c=R(20,60); const sum=k1+k2;
  if((total-c)%sum!==0) return genAngles();
  const xx=(total-c)/sum;
  if(xx<5||xx>60) return genAngles();
  const {ch,a:ai}=shuffleOpts(xx, [xx+5, total-c, 90-xx], [xx+2, xx-2, xx+10]);
  return {id:"G-GEO-"+Date.now()+R(1,999), d:"GEO", tier:"advanced",
    p:`In a triangle, two angles measure (${k1}x)° and (${k2}x)°, and the third angle measures ${c}°.`,
    q:"What is the value of x?", ch, a:ai,
    e:`Angle sum: ${k1}x + ${k2}x + ${c} = 180 → ${sum}x = ${180-c} → x = ${xx}. Check by substituting back into all three angles: they must total 180°.`};
}
window.GENERATORS = [genLinear, genSystem, genSlope, genIneq, genQuad, genExp, genPercent, genMean, genProb, genRatio, genSector, genTrig, genAngles];
})();

